const output = $json.output || '';
let parsed = {};
try {
  // Try to extract JSON from markdown fences or raw output
  const jsonMatch = output.match(/```(?:json)?\s*([\s\S]*?)```/);
  const jsonString = jsonMatch ? jsonMatch[1].trim() : output.trim();
  parsed = JSON.parse(jsonString);
} catch (e) {
  // If strict JSON parsing fails, try to find the first JSON object
  const looseMatch = output.match(/{[\s\S]*}/);
  if (looseMatch) {
    try {
      parsed = JSON.parse(looseMatch[0]);
    } catch {}
  }
}

return [{
  json: {
    intentRunId: parsed.intentRunId || '',
    decision: typeof parsed.decision === 'string' ? parsed.decision.toUpperCase() : '',
    actionType: parsed.actionType || '',
    recipient: parsed.recipient || '',
    subject: parsed.subject || '',
    body: parsed.body || '',
    message: parsed.message || '',
    rawOutput: output,
    parseError: !parsed.intentRunId ? 'Could not parse JSON from AI response' : undefined
  }
}];
